d": "79e4bb2e-da83-5e8a-8c8e-d4d10afc6644"}, {"name": "吴苗", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：吴苗。", "biography": null, "status": "draft", "id": "71def542-493a-53b0-9a58-d98583e52883"}, {"name": "李茂贞", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“岐王在唐亡后开府置百官”中为开府者。", "biography": null, "status": "draft", "id": "af9a00d1-c748-5b5f-9175-1af19530d83d"}, {"name": "薛知筹", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：薛知筹。", "biography": null, "status": "draft", "id": "de91426d-b6e8-558d-873c-90920b885ec9"}, {"name": "李昌符", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：李昌符。", "biography": null, "status": "draft", "id": "40f447e6-4770-5e94-9e87-b48375844b3d"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "霍存", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的霍存，在此段中为降朱全忠者。", "biography": null, "status": "draft", "id": "ed410902-d5ba-5b58-8e3d-6d97034263e7"}]'::jsonb)
