INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "常行儒杀王重荣", "start_year": 887, "end_year": 887, "time_original": "光启三年六月甲寅", "dynasty": "唐", "description": "河中牙将常行儒举兵攻府舍，王重荣逃出，次日被常行儒寻获杀害。史书称王重荣执法严厉、常行儒曾受罚。", "phases": [], "location_name": "河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "39b79f7a-8c15-545c-9e18-2ac9f695d75d"}, {"title": "朝廷任王重盈为护国节度使", "start_year": 887, "end_year": 887, "time_original": "王重荣遇害后；具体日未载", "dynasty": "唐", "description": "朝廷任陕虢节度使王重盈为护国节度使，并命其子王珙权知陕虢留后。", "phases": [], "location_name": "河中、陕虢", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "712a925a-9721-5481-b5ed-39d5663030aa"}, {"title": "王重盈至河中处死常行儒", "start_year": 887, "end_year": 887, "time_original": "王重盈抵河中后；具体日未载", "dynasty": "唐", "description": "王重盈到河中后拘捕常行儒并将其杀死。", "phases": [], "location_name": "河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "699450d9-d7ac-50e0-afb9-72164fe8d243"}, {"title": "毕师铎秦稠出城攻杨行密败", "start_year": 887, "end_year": 887, "time_original": "光启三年六月戊午", "dynasty": "唐", "description": "秦彦遣毕师铎、秦稠率军出城西击杨行密；秦稠战死，出击军损失惨重。", "phases": [], "location_name": "广陵城西", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f3ca8e9c-f9d2-5fec-b721-8cc1361470af"}, {"title": "广陵围城乏食", "start_year": 887, "end_year": 887, "time_original": "光启三年六月戊午前后", "dynasty": "唐", "description": "广陵城内粮食匮乏，樵采路断；原文接记“宣州军始食之”。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "67f5d40b-ea16-5a17-8b35-ccca7b2afffc"}, {"title": "谢殷逐宋兖", "start_year": 887, "end_year": 887, "time_original": "光启三年六月壬戌", "dynasty": "唐", "description": "亳州将领谢殷驱逐刺史宋兖。", "phases": [], "location_name": "亳州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "adb9f8db-7399-577d-8cfd-ab85b0c57b65"}, {"title": "李罕之与张全义据河阳东都", "start_year": 887, "end_year": 887, "time_original": "孙儒离河阳后；具体日未载", "dynasty": "唐", "description": "孙儒离开河阳后，李罕之召张全义合余众，分别据河阳和东都，并向河东求援。", "phases": [], "location_name": "泽州、河阳、东都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ed2adaf4-cfaf-5532-a068-660041928eb6"}, {"title": "李克用遣安金俊援河南", "start_year": 887, "end_year": 887, "time_original": "李罕之张全义求援后；具体日未载", "dynasty": "唐", "description": "李克用任安金俊为泽州刺史，派骑兵援助李罕之、张全义，并上表请任李罕之为河阳节度使、张全义为河南尹。", "phases": [], "location_name": "泽州、河阳、东都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "638532dc-3e94-58ac-8484-442ead2e4ddb"}, {"title": "东都战乱后人口凋敝", "start_year": null, "end_year": null, "time_original": "黄巢之乱后至张全义初到东都；具体年未载", "dynasty": "唐", "description": "《通鉴》追叙东都经黄巢之乱及后续战乱，张全义初到时城郭残破，居民极少。", "phases": [], "location_name": "东都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "68d0d0a5-3779-5ef0-aa04-d22ac434c9b6"}, {"title": "张全义设屯将招抚流散", "start_year": null, "end_year": null, "time_original": "张全义初治东都时；具体年日未载", "dynasty": "唐", "description": "张全义选十八人任屯将，往属县旧聚落招徕流散人口、劝农，并组织民众防御盗寇。", "phases": [], "location_name": "东都及属县", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1edf2198-94a8-5e73-9457-b841b0b0e290"}, {"title": "张全义治下东都逐年恢复", "start_year": null, "end_year": null, "time_original": "张全义初治东都数年之后；具体年未载", "dynasty": "唐", "description": "史书记张全义治理数年后东都坊曲、县户逐渐恢复，耕作扩大，并据户口恢复奏置令佐。", "phases": [], "location_name": "东都及属县", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "034d442d-d080-5489-a9c3-126bf170a200"}, {"title": "张全义奖农并督责荒田", "start_year": null, "end_year": null, "time_original": "张全义治东都期间；具体年未载", "dynasty": "唐", "description": "《通鉴》叙张全义察田桑、奖赏丰收农户，对荒田加以督责，并鼓励邻里相助。", "phases": [], "location_name": "东都及属县", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0fd67e87-6506-5617-9166-5f88d6e18c9c"}, {"title": "杜稜等败薛朗将李君暀", "start_year": 887, "end_year": 887, "time_original": "光启三年六月；具体日未载", "dynasty": "唐", "description": "杜稜等人在阳羡击败薛朗部将李君暀。", "phases": [], "location_name": "阳羡", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "02fc5114-7434-559e-89f9-61888fd72614"}, {"title": "吴苗率众降杨行密", "start_year": 887, "end_year": 887, "time_original": "光启三年七月癸未", "dynasty": "唐", "description": "淮南将吴苗率众越城投降杨行密。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a899a4fc-d2e8-5735-b6bb-d842080231f0"}, {"title": "李昌符于陇州被杀", "start_year": 887, "end_year": 887, "time_original": "光启三年八月壬寅朔", "dynasty": "唐", "description": "李茂贞上奏陇州刺史薛知筹献城，李昌符被斩，族属遭诛。", "phases": [], "location_name": "陇州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8d93af1a-7410-5a0f-aa9f-5604e9a2c3ce"}, {"title": "朱全忠遣霍存杀谢殷", "start_year": 887, "end_year": 887, "time_original": "光启三年八月；具体日未载", "dynasty": "唐", "description": "朱全忠经过亳州时遣霍存袭击谢殷，谢殷被斩。", "phases": [], "location_name": "亳州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "489d157f-7c12-5d69-a449-bdee9ee35f6c"}]'::jsonb)
