INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "河中牙将常行儒举兵攻府舍，王重荣逃出，次日被常行儒寻获杀害。史书称王重荣执法严厉、常行儒曾受罚。", "citation": "卷257·光启三年（887）·zztj-v257-y0887-p025·原文件第30行", "note": "原文：甲寅，河中牙将常行儒杀节度使王重荣。重荣用法严，末年尤甚。行儒尝被罚，耻之，遂作乱。夜，攻府舍，重荣逃于别墅。明旦，行儒得而杀之。制以陕虢节度使王重盈为护国节度使，又以重盈子珙权知陕虢留后。重盈至河中，执行儒，杀之。；核对说明：甲寅为起事日，王重荣被杀在“明旦”；不把两步强并为同日。关于起事动机依本书叙述。", "status": "draft", "id": "84871f6e-779f-5b41-97aa-e1a8558fae3b", "subject_id": "39b79f7a-8c15-545c-9e18-2ac9f695d75d", "source_id": "9512f2c9-5083-54ad-8bd4-1ef7a3ea30e6"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "光启三年六月甲寅", "citation": "卷257·光启三年（887）·zztj-v257-y0887-p025·原文件第30行", "note": "原文：甲寅，河中牙将常行儒杀节度使王重荣。重荣用法严，末年尤甚。行儒尝被罚，耻之，遂作乱。夜，攻府舍，重荣逃于别墅。明旦，行儒得而杀之。制以陕虢节度使王重盈为护国节度使，又以重盈子珙权知陕虢留后。重盈至河中，执行儒，杀之。；核对说明：甲寅为起事日，王重荣被杀在“明旦”；不把两步强并为同日。关于起事动机依本书叙述。", "status": "draft", "id": "a20bbbc3-60bc-5b4a-987d-03d453245578", "subject_id": "39b79f7a-8c15-545c-9e18-2ac9f695d75d", "source_id": "9512f2c9-5083-54ad-8bd4-1ef7a3ea30e6"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记常行儒：起事并杀王重荣者。", "citation": "卷257·光启三年（887）·zztj-v257-y0887-p025·原文件第30行", "note": "原文：甲寅，河中牙将常行儒杀节度使王重荣。重荣用法严，末年尤甚。行儒尝被罚，耻之，遂作乱。夜，攻府舍，重荣逃于别墅。明旦，行儒得而杀之。制以陕虢节度使王重盈为护国节度使，又以重盈子珙权知陕虢留后。重盈至河中，执行儒，杀之。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "97d6f0bd-ba25-5c78-9de9-2a8faf0ab747", "subject_id": "fa641548-8ae0-578c-b4a8-2201fd8a02ac", "source_id": "9512f2c9-5083-54ad-8bd4-1ef7a3ea30e6"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "常行儒：起事并杀王重荣者。", "citation": "卷257·光启三年（887）·zztj-v257-y0887-p025·原文件第30行", "note": "原文：甲寅，河中牙将常行儒杀节度使王重荣。重荣用法严，末年尤甚。行儒尝被罚，耻之，遂作乱。夜，攻府舍，重荣逃于别墅。明旦，行儒得而杀之。制以陕虢节度使王重盈为护国节度使，又以重盈子珙权知陕虢留后。重盈至河中，执行儒，杀之。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "2e3f4375-b1ca-5bee-bcc7-5ff75887